head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};

scwin.count = 0;

scwin.onpageload = function() {
	var bFormatter = function() {
		return [
			{
				'id' : 'custombtn',
				'className' : 'w2widget_btnCustom w2widget_btnCustom1',
				'isCustom' : true,
				'isCustomDirection': 'left'
			},
			{
				'id' : 'custombtn2',
				'isCustom' : true,
				'className' : 'w2widget_btnCustom w2widget_btnCustom2'
			},
			{
				'id' : 'custombtn3',
				'className' : 'w2widget_btnCustom3',
				'isCustom' : true,
				'isCustomDirection': 'left'
			},
			{'useDefault' : 'maximize'},
			{'useDefault' : 'close'}
		];
	};

	scwin.count++;
	ui_wgc_main.addWidgets({
		id : "widget" + scwin.count,
		title : "위젯!!!" + scwin.count,
		src : "/TEST_SP5/web5_test/SP2/2019/uiplugin/windowContainer/widget.xml",
		scope : true,
		x : 0,
		y : 0,
		unitWidth : 1,
		unitHeight : 1,
		buttonFormatter : bFormatter
	});
	scwin.count++;
	ui_wgc_main.addWidgets({
		id : "widget" + scwin.count,
		title : "위젯위젯~~~~~~" + scwin.count,
		src : "/TEST_SP5/web5_test/SP2/2019/uiplugin/windowContainer/widget.xml",
		scope : true,
		x : 1,
		y : 0,
		unitWidth : 1,
		unitHeight : 1
	});
	scwin.count++;
	ui_wgc_main.addWidgets({
		id : "widget" + scwin.count,
		title : "위젯" + scwin.count,
		src : "/TEST_SP5/web5_test/SP2/2019/uiplugin/windowContainer/widget.xml",
		scope : true,
		x : 2,
		y : 0,
		unitWidth : 1,
		unitHeight : 1,
		buttonFormatter : bFormatter
	});
};

scwin.checkVal = function(id) {
	let check_tagName1 = scwin.__getDom(id).previousElementSibling.tagName;
	let check_tagName2 = scwin.__getDom(id).nextElementSibling.tagName;

	return check_tagName1 == 'STRONG' && check_tagName2 == 'BUTTON';
};

scwin.checkVal2 = function(id) {
	let check_tagName1 = scwin.__getDom(id).previousElementSibling;
	let check_tagName2 = scwin.__getDom(id).nextElementSibling.tagName;

	return check_tagName1 === null && check_tagName2 == 'BUTTON';
};
